    aboutIntro: "Direktübersetzungen ergänzen die Shopify-Übersetzungen für Inhalte, die du sonst nicht erreichen kannst: 3rd-Party-Widgets (Reviews, Badges, Page-Builder) und alles andere, was direkt im Browser als Text gerendert wird.",
    aboutLearnMore: "Mehr erfahren",
    aboutDetails: "So funktioniert es: dein Theme-App-Embed (\"ContentPilot — Direct translation\") liest jeden Textknoten auf der Storefront, schlägt ihn in deinem Item-Wörterbuch nach und ersetzt ihn live durch die Übersetzung für die aktuelle Sprache. Das passiert client-seitig — perfekt für Widget-Labels und kurze App-Texte, aber NICHT von Suchmaschinen indexierbar. Für alles SEO-relevante (Produkttitel, Beschreibungen, Theme-Strings) nutze weiterhin die regulären Shopify-Feldübersetzungen. Apps, die ihre Inhalte in cross-origin iframes rendern (z. B. Loox-Reviews), können vom Embed nicht erreicht werden — das ist eine harte Browser-Grenze, keine Limitierung der App.",
    aboutWorkflow: "Workflow-Tipp: aktiviere das Embed unter „Theme bearbeiten → App-Embeds → ContentPilot — Direct translation\" (sonst läuft nichts auf der Storefront). Mit dem Capture-Tool im Theme-Editor (im Embed aktivierbar) kannst du Texte direkt per Klick erfassen statt sie händisch einzutippen. Über den Toggle „Texte von der Storefront sammeln\" werden zusätzlich automatisch alle unübersetzten Texte gesammelt, die echte Storefront-Besucher zu sehen bekommen — die kannst du im „Gefundene Texte\"-Modal in einem Rutsch als Items übernehmen.",
